def transform(grid):
    h, w = len(grid), len(grid[0])

    # A separator is a full row/column of one repeated color.
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    rb = [-1] + row_seps + [h]
    cb = [-1] + col_seps + [w]
    tiles = []
    for ri in range(len(rb) - 1):
        r0, r1 = rb[ri] + 1, rb[ri + 1]
        for ci in range(len(cb) - 1):
            c0, c1 = cb[ci] + 1, cb[ci + 1]
            if r0 < r1 and c0 < c1:
                tiles.append((r0, c0, r1, c1,
                              [grid[r][c0:c1] for r in range(r0, r1)]))

    sep_colors = [grid[r][0] for r in row_seps] + [grid[0][c] for c in col_seps]
    sep = sep_colors[0] if sep_colors else -1
    freq = {}
    for row in grid:
        for v in row:
            if v != sep:
                freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)

    # Pick the tile containing the most colored pattern cells and copy it to every tile.
    source_tile = max(tiles, key=lambda t: sum(v != bg for row in t[4] for v in row))[4]
    out = [row[:] for row in grid]
    for r0, c0, r1, c1, _ in tiles:
        for r in range(r1 - r0):
            for c in range(c1 - c0):
                out[r0 + r][c0 + c] = source_tile[r % len(source_tile)][c % len(source_tile[0])]
    return out
